import { createSelector } from '@ngrx/store';
import { findBoard, findTask } from '../../utils/boards';
import { boardsFeature } from './boards.reducer';

/** Generated by createFeature: one selector per state property. */
export const { selectBoards, selectLoaded, selectError } = boardsFeature;

/** One board by id; undefined if it doesn't exist. */
export const selectBoard = (boardId: string) =>
  createSelector(selectBoards, (boards) => findBoard(boards, boardId));

/** One task and its column (status); undefined if it doesn't exist. */
export const selectTask = (boardId: string, taskId: string) =>
  createSelector(selectBoards, (boards) => findTask(boards, boardId, taskId));
